		add(line(holder, 12, 1.5, 5.5, 10, 2.4), "BackgroundColor3")
		add(line(holder, 5.5, 10, 12.5, 8, 2.4), "BackgroundColor3")
		add(line(holder, 12.5, 8, 6, 16.5, 2.4), "BackgroundColor3")
	elseif kind == "globe" then
