		local function notifyStyle(head)
			local h = head:lower()
			if h:find("murderer") then
				return Color3.fromRGB(255, 70, 70), "!"
			end
			if h:find("sheriff") then
				return Color3.fromRGB(70, 150, 255), "!"
			end
			if h:find(": on") then
				return Color3.fromRGB(110, 230, 140), "check"
			end
			if h:find(": off") then
				return Color3.fromRGB(150, 150, 158), "cross"
			end
			return accentColor, "i"
		end

		local function layoutNotifications()
			local left = string.lower(tostring(notificationSide)) == "left"
			for i, t in ipairs(notifications) do
				local y = -20 - (i - 1) * 68
				t.card.AnchorPoint = left and Vector2.new(0, 1) or Vector2.new(1, 1)
				local pos = left and UDim2.new(0, 20, 1, y) or UDim2.new(1, -20, 1, y)
				tween(t.card, 0.35, { Position = pos }, Enum.EasingDirection.Out, Enum.EasingStyle.Quint)
			end
		end
		setNotificationSide = function(value)
			notificationSide = string.lower(tostring(value)) == "left" and "Left" or "Right"
			layoutNotifications()
		end

