				table.insert(cards, card)
				local thumb = create("Frame", { Size = UDim2.new(1, 0, 0, 102), BackgroundColor3 = cardColor, ZIndex = 2, Parent = card })
				addCorner(thumb, 8)
				strokes[item] = addStroke(thumb)
				create("ImageLabel", {
					AnchorPoint = Vector2.new(0.5, 0.5),
