					BackgroundTransparency = 1,
					ScaleType = Enum.ScaleType.Fit,
					Image = ("rbxthumb://type=%s&id=%s&w=150&h=150"):format(item.kind == "b" and "BundleThumbnail" or "Asset", idStr(item.id)),
