						local function linkParts(a, b)
							for _, ca in ipairs(a:GetChildren()) do
								local cb = b:FindFirstChild(ca.Name)
								if cb then
									if ca:IsA("BasePart") and cb:IsA("BasePart") then
										table.insert(links, { ca, cb })
