	local function refreshKeybindList()
		local lines = {}
		for _, b in ipairs(keybinds) do
			if b.key ~= Enum.KeyCode.Unknown then
				table.insert(lines, tostring(b.label) .. "  ·  " .. b.key.Name)
			end
		end
		keybindList.Text = table.concat(lines, "\n")
	end

	local function cloneValue(value)
		if type(value) == "table" then
			return table.clone(value)
		end
		return value
	end

	local function valuesEqual(a, b)
		if a == b then return true end
		if type(a) ~= "table" or type(b) ~= "table" then return false end
		for k, v in pairs(a) do if b[k] ~= v then return false end end
		for k, v in pairs(b) do if a[k] ~= v then return false end end
		return true
	end

	local function makeValue(id, default, callback)
		local obj = { _id = id, _value = cloneValue(default), _callback = callback, _listeners = {} }
		local function publish(value, runCallback, force)
			local changed = force or not valuesEqual(obj._value, value)
			obj._value = cloneValue(value)
			if not changed then return end
			obj._initialized = true
			local outgoing = cloneValue(obj._value)
			if runCallback and obj._callback then
				task.spawn(function() pcall(obj._callback, outgoing) end)
			end
			for _, listener in ipairs(obj._listeners) do
				task.spawn(function() pcall(listener, cloneValue(outgoing)) end)
			end
		end
		function obj:SetValue(value)
			if obj._uiSet then pcall(obj._uiSet, value, true) end
			if obj._setConfig then pcall(obj._setConfig, value) end
			publish(value, true, false)
		end
		function obj:OnChanged(fn)
			if type(fn) ~= "function" then return { Disconnect = function() end } end
			table.insert(obj._listeners, fn)
			local live = true
			return { Disconnect = function()
				if not live then return end
				live = false
				local i = table.find(obj._listeners, fn)
				if i then table.remove(obj._listeners, i) end
			end }
		end
		function obj:SetValues(values)
			if obj._uiSetValues then obj._uiSetValues(values or {}) end
		end
		function obj:_accept(value, runCallback)
			if obj._setConfig then pcall(obj._setConfig, value) end
			publish(value, runCallback ~= false, false)
		end
		function obj:_publishDefault()
			publish(obj._value, true, true)
		end
		setmetatable(obj, {
			__index = function(t, key)
				if key == "Value" then return rawget(t, "_value") end
				if key == "Transparency" then return rawget(t, "_transparency") end
				return nil
			end,
			__newindex = function(t, key, value)
				if key == "Value" then t:SetValue(value)
				elseif key == "Transparency" then rawset(t, "_transparency", value)
				else rawset(t, key, value) end
			end,
		})
		optionStore[id] = obj
		return obj
	end

	local function normalizeMulti(value)
		local result = {}
		if type(value) ~= "table" then return result end
		for k, v in pairs(value) do
			if type(k) == "number" then
				result[v] = true
			elseif v then
				result[k] = true
			end
		end
		return result
	end

	local function resizeLabelRow(section, row, height)
		for _, item in ipairs(section.items) do
			if item.row == row and item.h ~= height then
				local delta = height - item.h
				item.h = height
				row.Size = UDim2.new(1, -16, 0, height)
				for _, later in ipairs(section.items) do
					if later ~= item and later.y > item.y then
						later.y += delta
					end
				end
				section.y += delta
				section.height += delta
				layoutTab(section.tab)
				return
			end
		end
	end

	local function createLabel(group, text)
		local section = group._section
		local row, title = section:_row(tostring(text or ""), nil, 32)
		title.RichText = true
		title.TextWrapped = true
		title.TextTruncate = Enum.TextTruncate.None
		title.TextYAlignment = Enum.TextYAlignment.Center
		title.Size = UDim2.new(1, -20, 1, -4)
		local body
		local avatar
		local label = {}
		function label:Set(value, subtitle)
			value = tostring(value or "")
			if subtitle ~= nil then
				if not body then
					body = create("TextLabel", {
						Font = Enum.Font.Gotham,
						TextSize = 10,
						TextColor3 = mutedColor,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextYAlignment = Enum.TextYAlignment.Top,
						TextWrapped = true,
						RichText = true,
						BackgroundTransparency = 1,
						Position = UDim2.fromOffset(12, 29),
						Size = UDim2.new(1, -24, 1, -34),
						Parent = row,
					})
				end
				title.Text = tostring(subtitle)
				title.Position = UDim2.fromOffset(12, 5)
				title.Size = UDim2.new(1, -24, 0, 18)
				body.Text = value
				resizeLabelRow(section, row, 104)
			elseif #value > 80 or value:find("\n", 1, true) then
				title.Text = value
				title.Position = UDim2.fromOffset(12, 5)
				title.Size = UDim2.new(1, -24, 1, -10)
				title.TextYAlignment = Enum.TextYAlignment.Top
				resizeLabelRow(section, row, 74)
			else
				title.Text = value
			end
		end
		function label:SetText(value) self:Set(value) end
		function label:SetAvatar(image)
			if not avatar then
				avatar = create("ImageLabel", {
					BackgroundColor3 = elemColor,
					Position = UDim2.new(1, -62, 0, 8),
					Size = UDim2.fromOffset(48, 48),
					ScaleType = Enum.ScaleType.Crop,
					Parent = row,
				})
				addCorner(avatar, 8)
				title.Size = UDim2.new(1, -78, 1, -10)
			end
			avatar.Image = tostring(image or "")
		end
		function label:AddKeyPicker(id, opts)
			return group:_addKeyPicker(id, opts, title.Text)
		end
		function label:AddColorPicker(id, opts)
			return group:_addColorPicker(id, opts, title.Text)
		end
		function label:AddImage(id, opts)
			return group:AddImage(id, opts)
		end
		return label
	end

	local function addMultiDropdown(section, label, desc, values, default, callback)
		values = table.clone(values or {})
		local selected = normalizeMulti(default)
		local key = configKey(section, label)
		local row = section:_row(label, desc)
		local badge = create("TextButton", {
			Text = "0 selected",
			Font = Enum.Font.GothamMedium,
			TextSize = 10,
			TextColor3 = textColor,
			TextTruncate = Enum.TextTruncate.AtEnd,
			BackgroundColor3 = bgColor,
			AutoButtonColor = false,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -10, 0.5, 0),
			Size = UDim2.fromOffset(130, 24),
			Parent = row,
		})
		addCorner(badge, 6)
		local badgeStroke = addStroke(badge)
		create("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), Parent = badge })
		local popup, backdrop, closePopup
		local function refreshBadge()
			local count = 0
			local first
			for value, enabled in pairs(selected) do
				if enabled then count += 1; first = first or tostring(value) end
			end
			badge.Text = count == 0 and "0 selected" or (count == 1 and first or (tostring(count) .. " selected"))
		end
		local function emit(silent)
			refreshBadge()
			setConfig(key, selected)
			if not silent and callback then task.spawn(callback, table.clone(selected)) end
		end
		local function setValue(value, silent)
			selected = normalizeMulti(value)
			for k in pairs(selected) do
				if not table.find(values, k) then selected[k] = nil end
			end
			emit(silent)
		end
		local function close()
			if closePopup then closePopup() end
		end
		connect(badge.MouseButton1Click, function()
			if closePopup then close(); return end
			local visibleRows = math.max(1, math.min(#values, 7))
			local popupHeight = visibleRows * 26 + 8
			local rel = badge.AbsolutePosition - gui.AbsolutePosition
			local x = math.clamp(rel.X, 4, math.max(4, gui.AbsoluteSize.X - 174))
			local below = rel.Y + badge.AbsoluteSize.Y + 4
			local y = below + popupHeight <= gui.AbsoluteSize.Y - 4 and below or math.max(4, rel.Y - popupHeight - 4)
			backdrop = create("TextButton", { Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Size = UDim2.fromScale(1, 1), ZIndex = 149, Parent = gui })
			popup = create("Frame", { Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(170, popupHeight), BackgroundColor3 = panelColor, ZIndex = 150, Parent = gui })
			addCorner(popup, 7)
			create("UIStroke", { Color = accentColor, Transparency = 0.45, Thickness = 1, Parent = popup })
			local list = create("ScrollingFrame", { Position = UDim2.fromOffset(4, 4), Size = UDim2.new(1, -8, 1, -8), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = #values > 7 and 2 or 0, CanvasSize = UDim2.fromOffset(0, math.max(22, #values * 26)), ZIndex = 151, Parent = popup })
			closePopup = function()
				local p, b = popup, backdrop
				popup, backdrop, closePopup = nil, nil, nil
				if p and p.Parent then p:Destroy() end
				if b and b.Parent then b:Destroy() end
				tween(badgeStroke, 0.2, { Color = strokeColor })
			end
			connect(backdrop.MouseButton1Click, closePopup)
			for i, value in ipairs(values) do
				local chosen = selected[value] == true
				local option = create("TextButton", { Text = tostring(value), Font = chosen and Enum.Font.GothamBold or Enum.Font.GothamMedium, TextSize = 10, TextColor3 = chosen and accentColor or textColor, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, BackgroundColor3 = chosen and hoverColor or elemColor, AutoButtonColor = false, Position = UDim2.fromOffset(0, (i - 1) * 26), Size = UDim2.new(1, -2, 0, 22), ZIndex = 152, Parent = list })
				addCorner(option, 5)
				connect(option.MouseButton1Click, function()
					selected[value] = not selected[value] or nil
					local on = selected[value] == true
					option.Font = on and Enum.Font.GothamBold or Enum.Font.GothamMedium
					option.TextColor3 = on and accentColor or textColor
					option.BackgroundColor3 = on and hoverColor or elemColor
					emit(false)
				end)
			end
			tween(badgeStroke, 0.15, { Color = accentColor })
		end)
		refreshBadge()
		local function updateValues(newValues)
			values = table.clone(newValues or {})
			for k in pairs(selected) do if not table.find(values, k) then selected[k] = nil end end
			close()
			refreshBadge()
			setConfig(key, selected)
		end
		register(key, function(v) if type(v) == "table" then setValue(v, false) end end, function() return table.clone(selected) end, table.clone(selected))
		return {
			Get = function() return table.clone(selected) end,
			Set = setValue,
			Update = updateValues,
			SetValues = updateValues,
		}
	end

	local function parseKey(value)
		if typeof(value) == "EnumItem" and value.EnumType == Enum.KeyCode then return value end
		if type(value) == "string" and value ~= "" and value ~= "None" then
			local ok, key = pcall(function() return Enum.KeyCode[value] end)
			if ok and key then return key end
		end
		return Enum.KeyCode.Unknown
	end

	local function addKeyPicker(group, id, opts, labelText)
		opts = opts or {}
		local section = group._section
		local key = parseKey(opts.Default)
		local mode = opts.Mode or "Toggle"
		local callback = opts.Callback or opts.Func
		local obj = makeValue(id, key, callback)
		optionStore[id] = obj
		obj._key = key
		obj._mode = mode
		obj._active = false
		obj._label = opts.Text or labelText or id
		obj._syncToggle = opts.SyncToggleState
		obj._ownerToggle = group._lastToggle
		local function setKey(newKey)
			obj._key = parseKey(newKey)
			rawset(obj, "_value", obj._key)
			refreshKeybindList()
		end
		if not opts.NoUI then
			local control = section:Keybind(opts.Text or labelText or id, opts.Tooltip or opts.Description, function() return obj._key end, setKey)
			obj._uiSet = function(v) setKey(v) end
		end
		if id == "MenuKeybind" then
			setKey(key == Enum.KeyCode.Unknown and Enum.KeyCode.RightShift or key)
			obj._uiSet = function(v)
				setKey(v)
				toggleKey = obj._key
			end
			if obj._key ~= Enum.KeyCode.Unknown then toggleKey = obj._key end
			local configId = configKey(section, id)
			obj._rr9ConfigKey = configId
			register(configId, function(v)
				local parsed = parseKey(v)
				setKey(parsed)
				toggleKey = parsed
			end, function() return obj._key.Name end, obj._key.Name)
		end
		table.insert(keybinds, obj)
		refreshKeybindList()
		obj._uiSet = obj._uiSet or function(v) setKey(v) end
		obj.SetValue = function(self, v)
			local parsed = parseKey(v)
			setKey(parsed)
			if id == "MenuKeybind" then toggleKey = parsed end
			obj:_accept(parsed, true)
		end
		return obj
	end

	local function groupObject(section, tabName)
		local group = { _section = section, _tabName = tabName, _lastToggle = nil }
		function group:SetValue(value)
			if group._lastToggle then group._lastToggle:SetValue(value) end
		end
		function group:AddCheckbox(id, opts)
			opts = opts or {}
			local label = opts.Text or id
			local callback = opts.Callback or opts.Func
			local default = opts.Default
			if default == nil then default = false end
			local obj = makeValue(id, default, callback)
			toggleStore[id] = obj
			table.insert(allToggles, obj)
			local control = section:Toggle(label, opts.Tooltip or opts.Description, function(v) obj:_accept(v, true) end)
			obj._uiSet = function(v) control.Set(v, true) end
			obj._rr9ConfigKey = configKey(section, label)
			control.Set(default, true)
			group._lastToggle = obj
			table.insert(pendingDefaults, { object = obj, configKey = obj._rr9ConfigKey })
			function obj:AddKeyPicker(keyId, keyOpts) return addKeyPicker(group, keyId, keyOpts, label) end
			function obj:AddColorPicker(colorId, colorOpts) return group:_addColorPicker(colorId, colorOpts, label) end
			return obj
		end
		group.AddToggle = group.AddCheckbox
		function group:AddButton(arg1, arg2)
			local id, opts
			if type(arg1) == "string" then
				id = arg1
				if type(arg2) == "function" then opts = { Text = arg1, Callback = arg2 } else opts = arg2 or {} end
			else
				opts = arg1 or {}
				id = opts.Id or opts.Text or "Button"
			end
			local title = opts.Text or id
			local callback = opts.Callback or opts.Func
			local lastClick = 0
			local function invoke()
				if type(callback) == "function" then task.spawn(function() pcall(callback) end) end
			end
			local control = section:Button(title, opts.Tooltip or opts.Description, function()
				if opts.DoubleClick then
					local now = os.clock()
					if now - lastClick <= 0.45 then lastClick = 0; invoke() else lastClick = now end
				else
					invoke()
				end
			end)
			return control or { SetText = function(_, text) end }
		end
		function group:AddSlider(id, opts)
			opts = opts or {}
			local label = opts.Text or id
			local min = tonumber(opts.Min) or 0
			local max = tonumber(opts.Max) or 100
			if max <= min then max = min + 1 end
			local default = tonumber(opts.Default) or min
			local precision = math.clamp(math.floor(tonumber(opts.Rounding) or 0), 0, 4)
			local scale = 10 ^ precision
			local callback = opts.Callback or opts.Func
			local format = function(value)
				local number = value / scale
				local text = precision > 0 and string.format("%0." .. precision .. "f", number) or tostring(math.floor(number + 0.5))
				return text .. (opts.Suffix and tostring(opts.Suffix) or "")
			end
			local obj = makeValue(id, default, callback)
			local control = section:Slider(label, math.floor(min * scale + 0.5), math.floor(max * scale + 0.5), math.floor(default * scale + 0.5), function(v) obj:_accept(v / scale, true) end, format)
			obj._uiSet = function(v) control.Set(math.floor((tonumber(v) or default) * scale + 0.5), true) end
			obj._rr9ConfigKey = configKey(section, label)
			control.Set(math.floor(default * scale + 0.5), true)
			table.insert(pendingDefaults, { object = obj, configKey = obj._rr9ConfigKey })
			return obj
		end
		function group:AddDropdown(id, opts)
			opts = opts or {}
			local label = opts.Text or id
			local values = opts.Values or {}
			local default = opts.Default
			local callback = opts.Callback or opts.Func
			local obj = makeValue(id, opts.Multi and normalizeMulti(default) or default, callback)
			local control
			if opts.Multi then
				control = addMultiDropdown(section, label, opts.Tooltip or opts.Description, values, default, function(v) obj:_accept(v, true) end)
				obj._uiSet = function(v) control.Set(v, true) end
				obj._uiSetValues = function(v)
					control.SetValues(v)
					obj:_accept(control.Get(), true)
				end
			else
				local originalByDisplay = {}
				local displayByOriginal = {}
				local function rebuildMap(newValues)
					values = newValues or {}
					local displayValues = {}
					originalByDisplay, displayByOriginal = {}, {}
					for i, value in ipairs(values) do
						local display = type(value) == "table" and tostring(value.Text or value.Name or value.Value or i) or tostring(value)
						table.insert(displayValues, display)
						originalByDisplay[display] = value
						displayByOriginal[value] = display
					end
					return displayValues
				end
				local displayValues = rebuildMap(values)
				local effectiveDefault = default
				if type(default) == "number" and not table.find(values, default) and values[default] ~= nil then effectiveDefault = values[default] end
				local defaultDisplay = displayByOriginal[effectiveDefault]
				control = section:Dropdown(label, opts.Tooltip or opts.Description, displayValues, opts.Placeholder or "select...", function(display)
						obj:_accept(originalByDisplay[display], true)
					end, opts.Searchable == true)
				obj._uiSet = function(v)
					local display = displayByOriginal[v] or (v ~= nil and tostring(v) or nil)
					control.Set(display, true)
				end
				obj._uiSetValues = function(v)
					local nextDisplays = rebuildMap(v)
					control.Update(nextDisplays)
					local currentDisplay = control.Get()
					obj:_accept(currentDisplay and originalByDisplay[currentDisplay] or nil, true)
				end
				if effectiveDefault ~= nil and defaultDisplay then control.Set(defaultDisplay, true); rawset(obj, "_value", effectiveDefault) end
				local configId = configKey(section, label)
				obj._rr9ConfigKey = configId
				obj._setConfig = function(v) setConfig(configId, v) end
				register(configId, function(v) obj:SetValue(v) end, function() return cloneValue(obj.Value) end, effectiveDefault)
			end
			if opts.Multi then obj._rr9ConfigKey = configKey(section, label) end
			table.insert(pendingDefaults, { object = obj, configKey = obj._rr9ConfigKey })
			return obj
		end
		function group:AddInput(id, opts)
			opts = opts or {}
			local label = opts.Text or id
			local default = tostring(opts.Default or "")
			local callback = opts.Callback or opts.Func
			local obj = makeValue(id, default, callback)
			local control = section:Input(label, opts.Tooltip or opts.Description, opts.Placeholder or "enter text", function(v)
				if opts.NumbersOnly then v = tostring(v):gsub("[^%d%.%-]", "") end
				obj:_accept(v, true)
			end)
			obj._uiSet = function(v) control.Set(tostring(v or "")) end
			obj._rr9ConfigKey = configKey(section, label)
			obj._setConfig = function(v) setConfig(obj._rr9ConfigKey, tostring(v or "")) end
			control.Set(default)
			register(obj._rr9ConfigKey, function(v) obj:SetValue(tostring(v or "")) end, function() return tostring(obj.Value or "") end, default)
			table.insert(pendingDefaults, { object = obj, configKey = obj._rr9ConfigKey })
			return obj
		end
		function group:AddColorPicker(id, opts)
			return group:_addColorPicker(id, opts, nil)
		end
		function group:_addKeyPicker(id, opts, contextLabel)
			return addKeyPicker(group, id, opts, contextLabel)
		end
		function group:_addColorPicker(id, opts, contextLabel)
			opts = opts or {}
			local label = opts.Title or opts.Text or contextLabel or id
			local default = typeof(opts.Default) == "Color3" and opts.Default or Color3.fromRGB(255, 255, 255)
			local callback = opts.Callback or opts.Func
			local obj = makeValue(id, default, callback)
			obj._transparency = tonumber(opts.Transparency) or 0
			local control = section:ColorPicker(label, opts.Tooltip or opts.Description, default, function(v) obj:_accept(v, true) end)
			obj._uiSet = function(v) if typeof(v) == "Color3" then control.Set(v, true) end end
			obj._rr9ConfigKey = configKey(section, label)
			if opts.Transparency then
				local alpha = section:Slider(label .. " Opacity", 0, 100, math.floor(obj._transparency * 100 + 0.5), function(v)
					obj._transparency = v / 100
					if callback then callback(obj._value) end
				end, function(v) return tostring(v) .. "%" end)
				obj._setAlpha = function(v) obj._transparency = math.clamp(tonumber(v) or 0, 0, 1); alpha.Set(math.floor(obj._transparency * 100 + 0.5), true) end
			end
			table.insert(pendingDefaults, { object = obj, configKey = obj._rr9ConfigKey })
			return obj
		end
		function group:AddLabel(text)
			return createLabel(group, text)
		end
		function group:AddDivider()
			local row = section:_row("", nil, 12)
			row.BackgroundTransparency = 1
			create("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UDim2.new(1, -14, 0, 1), BackgroundColor3 = strokeColor, BorderSizePixel = 0, Parent = row })
		end
		function group:AddImage(id, opts)
			opts = opts or {}
			local row, title = section:_row(opts.Text or id, nil, 82)
			title.Visible = false
			local image = create("ImageLabel", { Name = id, Image = tostring(opts.Image or "rbxassetid://0"), BackgroundColor3 = elemColor, BackgroundTransparency = 0, Position = UDim2.fromOffset(8, 6), Size = UDim2.new(1, -16, 1, -12), ScaleType = Enum.ScaleType.Fit, Parent = row })
			addCorner(image, 8)
			local handle = { _image = image }
			function handle:SetImage(value) image.Image = tostring(value or "rbxassetid://0") end
			function handle:Set(value) self:SetImage(value) end
			return setmetatable(handle, { __index = function(t, k) if k == "Image" then return image.Image end end, __newindex = function(t, k, v) if k == "Image" then image.Image = tostring(v or "") else rawset(t,k,v) end end })
		end
		function group:AddViewport(id, opts)
			opts = opts or {}
			local height = math.clamp(tonumber(opts.Height) or 170, 90, 260)
			local row, title = section:_row(opts.Text or id, nil, height + 10)
			local viewport = create("ViewportFrame", { Name = id, BackgroundColor3 = bgColor, Position = UDim2.fromOffset(8, 5), Size = UDim2.new(1, -16, 1, -10), Ambient = Color3.fromRGB(190, 190, 190), LightColor = Color3.fromRGB(255, 255, 255), LightDirection = Vector3.new(-1, -1, -1), Parent = row })
			addCorner(viewport, 8)
			local worldModel = Instance.new("WorldModel")
			worldModel.Parent = viewport
			local camera = opts.Camera or Instance.new("Camera")
			camera.Parent = viewport
			viewport.CurrentCamera = camera
			local handle = { _viewport = viewport, _world = worldModel }
			function handle:SetObject(object)
				worldModel:ClearAllChildren()
				if not object then return end
				local clone = object:Clone()
				clone.Parent = worldModel
				if clone:IsA("Model") then
					local cf, size = clone:GetBoundingBox()
					clone:PivotTo(CFrame.new(0, 0, 0))
					local radius = math.max(size.X, size.Y, size.Z, 2)
					camera.CFrame = CFrame.new(Vector3.new(0, size.Y * 0.15, radius * 2.4), Vector3.new(0, size.Y * 0.15, 0))
				elseif clone:IsA("BasePart") then
					clone.CFrame = CFrame.new()
					camera.CFrame = CFrame.new(0, 0, 6)
				end
			end
			function handle:SetCamera(newCamera)
				if newCamera then camera = newCamera; camera.Parent = viewport; viewport.CurrentCamera = camera end
			end
			if opts.Object then pcall(function() handle:SetObject(opts.Object) end) end
			return handle
		end
		return group
	end

	local function trackConnection(signal, callback)
		local ok, connection = pcall(function() return signal:Connect(callback) end)
		if ok and connection then table.insert(connections, connection); return connection end
		return nil
	end

	trackConnection(UserInputService.InputBegan, function(input, gameProcessed)
		if gameProcessed or input.UserInputType ~= Enum.UserInputType.Keyboard or keyListener then return end
		for _, bind in ipairs(keybinds) do
			if bind._key == input.KeyCode and bind._key ~= Enum.KeyCode.Unknown then
				if bind._mode == "Toggle" then
					bind._active = not bind._active
					if bind._syncToggle and bind._ownerToggle then bind._ownerToggle:SetValue(bind._active) end
					bind:_accept(bind._active, true)
				elseif bind._mode == "Hold" then
					bind._active = true
					bind:_accept(true, true)
				else
					if bind._callback then task.spawn(function() pcall(bind._callback, true) end) end
				end
			end
		end
	end)
	trackConnection(UserInputService.InputEnded, function(input)
		if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
		for _, bind in ipairs(keybinds) do
			if bind._key == input.KeyCode and bind._mode == "Hold" and bind._active then
				bind._active = false
				if bind._callback then task.spawn(function() pcall(bind._callback, false) end) end
			end
		end
	end)

	local tabObjectMeta = {}
	tabObjectMeta.__index = function(self, key)
		if key == "AddLeftGroupbox" or key == "AddRightGroupbox" then
			return function(_, title, icon)
				local section = addSection(self._tab, tostring(title or "RR9"))
				return groupObject(section, self._sourceName)
			end
		end
		return rawget(self, key)
	end
	local function wrapTab(sourceName, iconName)
		if rr9Tabs[sourceName] then return rr9Tabs[sourceName] end
		local page = tabAliases[sourceName]
		if not page then
			local display = sourceName == "Tp" and "RR9 Teleport" or (sourceName == "Keybind" and "RR9 Keybinds" or ((sourceName == "MapBreak" or sourceName == "MapBreaks") and "RR9 Map Breaks" or ("RR9 " .. sourceName)))
			page = addTab(display, iconName or "settings", "9rr · Fling Things and People")
		end
		local wrapped = setmetatable({ _tab = page, _sourceName = sourceName }, tabObjectMeta)
		rr9Tabs[sourceName] = wrapped
		return wrapped
	end

	local backgroundImage
	local window = {}
	function window:AddTab(name, iconName) return wrapTab(tostring(name), iconName) end
	function window:SetBackgroundImage(image)
		if not backgroundImage then
			backgroundImage = create("ImageLabel", { Name = "RR9Background", BackgroundTransparency = 1, ImageTransparency = 0.15, ScaleType = Enum.ScaleType.Crop, Size = UDim2.fromScale(1, 1), ZIndex = 0, Parent = main })
			backgroundImage.LayoutOrder = -100
		end
		backgroundImage.Image = tostring(image or "rbxassetid://0")
	end
	function window:SetBackgroundTransparency(value)
		if backgroundImage then backgroundImage.ImageTransparency = math.clamp(tonumber(value) or 0, 0, 1) end
	end
	function window:SetCornerRadius(radius)
		local corner = main:FindFirstChildOfClass("UICorner")
		if corner then corner.CornerRadius = UDim.new(0, math.clamp(tonumber(radius) or 10, 0, 36)) end
	end

	local library = {
		Options = optionStore,
		Toggles = toggleStore,
		KeybindFrame = rr9KeybindFrame,
		ShowCustomCursor = true,
	}
	function library:CreateWindow(_) return window end
	function library:SetShowCustomCursor(value) customCursorEnabled = value == true; self.ShowCustomCursor = customCursorEnabled end
	function library:Notify(data)
		data = data or {}
		local head = tostring(data.Title or data.TitleText or "RR9")
		local body = tostring(data.Description or data.Content or "")
		if type(notify) == "function" then pcall(notify, head, body) end
	end
	function library:SetNotifySide(value) if type(setNotificationSide) == "function" then setNotificationSide(value) end end
	function library:SetDPIScale(value)
		local n = tonumber(value)
		if n then
			local scale = math.clamp(n / 100, 0.5, 2)
			if mainScale then mainScale.Scale = scale end
		end
	end
	function library:Unload()
		if _G.RockHubUnload then pcall(_G.RockHubUnload) end
	end
	function library:AddDraggableLabel(text)
		local label = create("TextLabel", {
			Name = "RR9Watermark",
			Text = tostring(text or "9rr"),
			Font = Enum.Font.GothamBold,
			TextSize = 11,
			TextColor3 = textColor,
			BackgroundColor3 = panelColor,
			BackgroundTransparency = 0.08,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(12, 108),
			Size = UDim2.fromOffset(220, 28),
			ZIndex = 60,
			Parent = gui,
		})
		addCorner(label, 8)
		addStroke(label, accentColor)
		create("UIPadding", { PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9), Parent = label })
		makeDraggable(label, "rr9/watermark-position")
		return { SetText = function(_, value) label.Text = tostring(value or "") end }
	end
	local themeManager = {}
	function themeManager:SetLibrary(_) end
	function themeManager:SetFolder(_) end
	function themeManager:ApplyToTab(tab)
		if tab and tab.AddLeftGroupbox then
			local g = tab:AddLeftGroupbox("RR9 Appearance", "palette")
			g:AddLabel("RR9 controls use the current RockHub theme.")
		end
	end
	local saveManager = {}
	function saveManager:SetLibrary(_) end
	function saveManager:IgnoreThemeSettings() end
	function saveManager:SetIgnoreIndexes(_) end
	function saveManager:SetFolder(_) end
	function saveManager:SetSubFolder(_) end
	function saveManager:BuildConfigSection(tab)
		if tab and tab.AddRightGroupbox then
			local g = tab:AddRightGroupbox("RR9 Settings", "save")
			g:AddLabel("RR9 values are saved with the existing RockHub profile.")
		end
	end

	function RR9Compat.FlushDefaults()
		for _, entry in ipairs(pendingDefaults) do
			if not entry.object._initialized then entry.object:_publishDefault() end
		end
		updateSidebarCanvas()
	end
	function RR9Compat.Unload()
		if RR9Compat.PrivateEnv then RR9Compat.PrivateEnv.RR9_Stopped = true end
		customCursorEnabled = false
		customCursor.Visible = false
		UserInputService.MouseIconEnabled = originalMouseIconEnabled
		for _, toggle in ipairs(allToggles) do
			if toggle.Value then pcall(function() toggle:SetValue(false) end) end
		end
		for _, bind in ipairs(keybinds) do
			if bind._active then
				bind._active = false
				if bind._syncToggle and bind._ownerToggle then pcall(function() bind._ownerToggle:SetValue(false) end) end
				if bind._callback then task.spawn(function() pcall(bind._callback, false) end) end
			end
		end
	end
	RR9Compat.Library = library
	RR9Compat.Window = window
	RR9Compat.ThemeManager = themeManager
	RR9Compat.SaveManager = saveManager
	RR9Compat.Options = optionStore
	RR9Compat.Toggles = toggleStore
	RR9Compat.WrapTab = wrapTab
	RR9Compat.TrackConnection = trackConnection
end

		local function __RR9Init()
			local function rr9Track(signal, callback)
				return RR9Compat.TrackConnection(signal, callback)
			end
