			function startSound()
			    if not enabled then return end
			    if typingSound.SoundId and typingSound.SoundId ~= '' then
			        if not typingSound.IsPlaying then
			            typingSound:Play()
			        end
			    end
			end

			function stopSound()
			    typingSound:Stop()
			end

