			DefL:AddCheckbox("AntiPaint", {
			    Text = "Anti Paint",
			    Default = false,
			    Callback = function(Value)
			        if Value then
			            pcall(function()
			                for _, obj in ipairs(workspace:GetDescendants()) do
			                    if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
			                        clone = obj:Clone()
			                        clone.Archivable = true
			                        paintPartsBackup[obj:GetDebugId()] = { clone = clone, parent = obj.Parent }
			                        obj:Destroy()
			                    end
			                end
			            end)
			            
			            table.insert(paintConnections, rr9Track(workspace.DescendantAdded,(function(obj)
			                if obj:IsA("BasePart") and obj.Name == "PaintPlayerPart" then
			                    task.defer(function()
			                        if obj and obj.Parent then
			                            clone = obj:Clone()
			                            clone.Archivable = true
			                            paintPartsBackup[obj:GetDebugId()] = { clone = clone, parent = obj.Parent }
			                            obj:Destroy()
			                        end
			                    end)
			                end
			            end)))
			            
			            char = workspace:FindFirstChild(LocalPlayer.Name)
			            if char then
			                for _, v in ipairs(char:GetChildren()) do
			                    if v:IsA("Part") or v:IsA("BasePart") then
			                        v.CanTouch = false
			                        v.CanQuery = false
			                    end
			                end
			            end
			        else
			            for _, data in pairs(paintPartsBackup) do
			                if data.clone and data.parent then
			                    data.clone.Parent = data.parent
			                end
			            end
			            paintPartsBackup = {}
			            for _, conn in ipairs(paintConnections) do
