			    Callback = function(Value)
			        hkExpectDeath = false
			        hkSalmonList = {}
			        hkSalmonList[LocalPlayer.UserId] = true
			        
			        local function hkApplySalmon(char)
			            if not char then return end
			            newHum = char:WaitForChild("Humanoid", 5)
