			                root2 = c2 and c2:FindFirstChild("HumanoidRootPart")
			                if root2 then
			                    assembly = root2.AssemblyRootPart or root2
			                    assembly.AssemblyLinearVelocity = Vector3.zero
			                    assembly.AssemblyAngularVelocity = Vector3.zero
			                end
			            end)
			            ocnGroovPos = nil
			        end
			    end
			})

