			do

			DestroyTargetGucciActive = false

			TgtR:AddCheckbox("DestroyTargetGucci", {
			    Text = "[SIT] Remove Target Gucci",
			    Default = false,
			    Callback = function(Value)
			        DestroyTargetGucciActive = Value
			        if Value then
			            target = getSelectedPlayer()
			            if not target then
