			function IsDescOf(target, ancestor)
			    local c = target.Parent

			    while c do
			        if c == ancestor then
			            return true
			        end

			        c = c.Parent
			    end

			    return false
			end
			function CleanConns(t)
			    for _, c in ipairs(t)do
