			function MakeMovers(part, pos, rot)
			    local bp = Instance.new('BodyPosition')

			    bp.P = 15000
			    bp.D = 200
			    bp.MaxForce = Vector3.new(5e6, 5e6, 5e6)
			    bp.Position = pos
			    bp.Parent = part

			    local bg = Instance.new('BodyGyro')

			    bg.P = 15000
			    bg.D = 200
			    bg.MaxTorque = Vector3.new(5e6, 5e6, 5e6)
			    bg.CFrame = rot
