			end))
			PanelTools:AddCheckbox('cbGrabMaster', {
			    Text = 'Enable Grabs',
			    Tooltip = 'Instantly enables or disables every selected grab',
			    Default = false,
			}):OnChanged(function(v)
			    GrabMasterOn = v

			    for name, active in pairs(GrabEnabled)do
