			    Values = GrabOptions,
			    Default = {},
			    Multi = true,
			}):OnChanged(function(selectedMap)
			    for _, name in ipairs(GrabOptions)do
			        local wanted = selectedMap[name] == true
			        local current = GrabEnabled[name] == true

			        if wanted ~= current then
			            GrabEnabled[name] = wanted

