			    Default = 30,
			    Min = 1,
			    Max = 2000,
			    Rounding = 0,
			}):OnChanged(function(v)
			    MasslessSense = math.max(1, v or MasslessSense)
			end)
			PanelTools:AddSlider('slExtendLineForce', {
			    Text = 'Scroll Step Power',
			    Tooltip = 'Distance moved per mouse wheel tick.',
			    Default = 7,
			    Min = 1,
			    Max = 25,
