			getgenv().process = function()
			    if isProcessing then
			        return
			    end

			    isProcessing = true

			    if not currentDecoy or not currentDecoy.Parent or not currentDecoy:GetAttribute(UNIQUE_ATTRIBUTE) then
			        if isEnabled then
			            spawnDecoy()
			        end
			    else
			        setupFling(currentDecoy)
			    end

			    isProcessing = false
			end

