			    isEnabled = state

			    if state then
			        process()
			    else
			        isProcessing = false

			        if conn then
			            conn:Disconnect()
			        end

			        for toy, mon in pairs(ownershipMonitors)do
			            mon:Disconnect()
			        end

			        ownershipMonitors = {}

