			                    if ownedFor > longestTime then
			                        longestTime = ownedFor
			                    end
			                end
			            end

			            if isLocalOwner then
			                if not getgenv().MyPlotClaimStart[selected] then
			                    getgenv().MyPlotClaimStart[selected] = tick()
			                end
			            else
			                getgenv().MyPlotClaimStart[selected] = nil
