			    DoubleClick = false
			})

			bgData = {
			    Enabled = true,
			    Image = "0",
			    Last = nil,
			    Transparency = 0.15
			}

			bgToken = 0

			local function formatImage(id)
			    id = tostring(id or ""):gsub("%s+", "")
			    if id == "" then
			        return "rbxassetid://0"
			    end
			    if id:find("rbxassetid://") then
			        return id
			    end
			    return "rbxassetid://" .. id
			end

			local function applyBackground()
			    bgToken = bgToken + 1
			    current = bgToken
			    
			    task.delay(0.05, function()
			        if current ~= bgToken then
			            return
			        end
			        
			        image = bgData.Enabled and formatImage(bgData.Image) or "rbxassetid://0"
			        
			        if bgData.Last == image then
			            return
			        end
			        
			        bgData.Last = image
			        
			        pcall(function()
			            Window:SetBackgroundImage(image)
			            Window:SetBackgroundTransparency(bgData.Transparency)
			        end)
			    end)
			end

			BackGroup:AddCheckbox("EnableBackground", {
			    Text = "Enable Background",
			    Default = true,
			    Callback = function(Value)
			        bgData.Enabled = Value
			        applyBackground()
			    end
			})

			BackGroup:AddInput("BackgroundAsset", {
			    Text = "Asset ID",
			    Default = "0",
			    Callback = function(Value)
			        bgData.Image = tostring(Value)
			        applyBackground()
			    end
			})

			BackGroup:AddButton({
			    Text = "Clear Background",
			    Callback = function()
			        bgData.Image = "0"
			        applyBackground()
			    end
			})

			applyBackground()

			Library.ToggleKeybind = Options.MenuKeybind

			ThemeManager:SetLibrary(Library)
			SaveManager:SetLibrary(Library)
			SaveManager:IgnoreThemeSettings()
			SaveManager:SetIgnoreIndexes({ "MenuKeybind" })
			ThemeManager:SetFolder("9rr")
			SaveManager:SetFolder("9rr/Configs")
			SaveManager:SetSubFolder("game-config")

			ThemeManager:ApplyToTab(Tabs.UISettings)
			SaveManager:BuildConfigSection(Tabs.UISettings)

			Window:SetCornerRadius(20)
			Library:SetShowCustomCursor(true)
			watermark = Library:AddDraggableLabel("•9rr | 0 FPS | 0 ms")

			task.spawn(function()
			    while task.wait(0.5) do
			        fps = math.floor(1 / game:GetService("RunService").RenderStepped:Wait())
			        ping = math.floor(game:GetService('Stats').Network.ServerStatsItem['Data Ping']:GetValue())
			        watermark:SetText(string.format("•9rr | %d FPS | %d ms", fps, ping))
			    end
			end)

			end

			print("9rr Loaded, Sir3n and Oat is the goat frfr")

			end
		end
		local __rr9EnvBase = (type(getgenv) == "function" and getgenv()) or _G
		local __rr9PrivateEnv = setmetatable({}, { __index = __rr9EnvBase })
		__rr9PrivateEnv._G = __rr9PrivateEnv
		__rr9PrivateEnv.getgenv = function() return __rr9PrivateEnv end
		__rr9PrivateEnv.RR9_Stopped = false
		local __rr9EnvApplied = false
		if type(setfenv) == "function" then __rr9EnvApplied = pcall(setfenv, __RR9Init, __rr9PrivateEnv) end
		if not __rr9EnvApplied then __rr9PrivateEnv = _G end
		RR9Compat.PrivateEnv = __rr9PrivateEnv
		local __rr9Ok, __rr9Error = pcall(__RR9Init)
		if not __rr9Ok then
			warn("RR9 initialization error: " .. tostring(__rr9Error))
			if type(notify) == "function" then pcall(notify, "RR9", "Initialization failed; see executor output") end
		end

		selectTab(mainTab)
